public static Matrix4x4 Create(Quaternion Q)
    {

        float x2 = Q.x + Q.x;
        float y2 = Q.y + Q.y;
        float z2 = Q.z + Q.z;

        float x2x = x2 * Q.x;
        float x2y = x2 * Q.y;
        float x2z = x2 * Q.z;
        float x2w = x2 * Q.w;
        float y2y = y2 * Q.y;
        float y2z = y2 * Q.z;
        float y2w = y2 * Q.w;
        float z2z = z2 * Q.z;
        float z2w = z2 * Q.w;

        Matrix4x4 mat = new Matrix4x4();

        mat.m00 = 1.0f - (y2y + z2z);
        mat.m01 = (x2y - z2w);
        mat.m02 = (x2z + y2w);
        mat.m03 = 0.0f;

        mat.m10 = (x2y + z2w);
        mat.m11 = 1.0f - (x2x + z2z);
        mat.m12 = (y2z - x2w);
        mat.m13 = 0.0f;

        mat.m20 = (x2z - y2w);
        mat.m21 = (y2z + x2w);
        mat.m22 = 1.0f - (x2x + y2y);
        mat.m23 = 0.0f;

        mat.m30 = 0.0f;
        mat.m31 = 0.0f;
        mat.m32 = 0.0f;
        mat.m33 = 1.0f;

        return mat;
    }
